"use strict";(self.webpackChunkuxcam=self.webpackChunkuxcam||[]).push([[2330],{589:function(e,t,a){a.r(t),a.d(t,{Head:function(){return l},default:function(){return c}});var s=a(96540),r=a(86997),n=a(54727);var o={seo:{title:"Case study | Recora",description:"Discover how Recora reduced support tickets by 42% after using UXCam",image:"https://images.ctfassets.net/vv1yxl437u7d/3Mn0AbpUmb4aFxUXNgpzY6/77b23638bee2a4c3cc29e6336ace2e1f/metaimageNEW.png"},hero:{industry:"Health and Fitness",title:"How Recora <span>Reduced Support Tickets by 42% with UXCam</span>",description:"Recora is redefining the future of heart health by offering a virtual cardiac rehabilitation app, helping heart procedure patients recover from home. Through the app, users join live coaching sessions, track their progress, and stay connected with their healthcare providers.",featuresUsed:[{label:"Session Replay",url:"/experience-analytics/session-replay"},{label:"Heatmaps",url:"/experience-analytics/heatmaps"},{label:"Event Analytics",url:"/product-analytics/smart-events"},{label:"Funnels",url:"/product-analytics/funnels"}],image:"https://images.ctfassets.net/vv1yxl437u7d/1SXnmgXsgaXOpXD44p19NI/3ccab314a400311dd0bc7bf23d16c587/Recora_logo_white.svg",vimeoId:"844183869?h=bfb81d3dc8"},stats:[{value:"4x increase",label:"in heart health program completion rates"},{value:"42% reduction",label:"in users complaining about a bad experience"},{value:"30% decrease",label:"in user frustration signals (rage taps)"}],challenge:{title:"The Challenge",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/1Ov4GcUZwhwz6Gdk7x9TIS/ad9823ae58f2e2026f64d865f820a987/Vector.svg",paragraphs:["Many users, largely an older demographic, couldn't reliably interact with the critical 'join session' button. The team received constant calls from frustrated patients saying their tablets weren't working, causing them to miss scheduled sessions with their doctors.","Without any way to see what was happening on-screen, the team tried troubleshooting over the phone. But the users' limited familiarity with technology made remote fixes nearly impossible, and most cases ended with the tablet shipped back for replacement.","Recora had been using Mixpanel for analytics, but page views alone told them very little about why users were struggling. They needed a HIPAA-compliant tool with Flutter support.","UXCam stood out from the start. Questions were answered within hours, and Recora's product team felt genuinely understood and supported."],quote:{text:"The majority of the time when someone said 'this is broken', it wasn't really broken, it was something that could be solved. We just didn't have the information we needed to solve it.",author:"Emma Cancelliere-Stanton",role:"Head of Product",image:"https://images.ctfassets.net/vv1yxl437u7d/5fUdGlqKehCvVSzuG2cbdf/c2e3499daebc1e61c55498c5b6b4ae25/1644634809457.jpeg"}},solution:{title:"The Solution",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/28xui9UzDyaFzt7EfaJuio/74b1070ae5cc420b5ac71c1dee040858/Vector.svg",paragraphs:["Using UXCam's <a href=\"/experience-analytics/heatmaps\">heatmaps</a>, the team quickly saw why users were struggling. Instead of tapping the 'join session' button, they were holding it down like a physical remote control button, which wouldn't trigger the action.",'<a href="/experience-analytics/session-replay">Session recordings</a> confirmed the issue: the button was timing out and the session wouldn\'t start once users lifted their finger.',"The fix was straightforward. Instead of only supporting a tap, they enabled a press-and-hold gesture to trigger the button. Recora now resolves these issues remotely, with no more tablets shipped back as 'faulty'."],quote:{text:"Session replay has been a lifesaver for us.",author:"Emma Cancelliere-Stanton",role:"Head of Product",image:"https://images.ctfassets.net/vv1yxl437u7d/5fUdGlqKehCvVSzuG2cbdf/c2e3499daebc1e61c55498c5b6b4ae25/1644634809457.jpeg"}},whatsNext:{title:"The Result",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/Bc9n79vDsJLoV0HUy6g4j/db1b14e3e0162ced77ac4f4e7f6b5e6a/Path-7.svg",paragraphs:["Thanks to a few small changes like this, Recora has seen:<ul><li>42% decrease in support tickets related to the 'join session' button not working</li><li>1/3 of devices previously returned as 'faulty' no longer needed to be sent back</li><li>30% decrease in rage taps</li></ul>",'Beyond the button fix, Recora now uses <a href="/experience-analytics/session-replay">session replay</a> to proactively spot issues across the app.',"When the team sees a user struggling, like repeatedly trying to upload a photo to their food journal before closing the app, they reach out directly with guidance, turning a frustrating experience into a supported one."],quote:{text:"I really felt like we were being listened to, we moved through contracting so quickly and so seamlessly. It was one of the easiest platforms I think we've ever had to implement.",author:"Emma Cancelliere-Stanton",role:"Head of Product",image:"https://images.ctfassets.net/vv1yxl437u7d/5fUdGlqKehCvVSzuG2cbdf/c2e3499daebc1e61c55498c5b6b4ae25/1644634809457.jpeg"}}},i=a(17437);const l=()=>(0,i.Y)(s.Fragment,null,(0,i.Y)(n.A,{title:o.seo.title,description:o.seo.description,image:{file:{url:o.seo.image}}}),(0,i.Y)("link",{rel:"canonical",href:"https://uxcam.com/case-study/recora/"}),(0,i.Y)("link",{rel:"alternate",hrefLang:"en",href:"https://uxcam.com/case-study/recora/"}),(0,i.Y)("link",{rel:"alternate",hrefLang:"es",href:"https://uxcam.com/es/case-study/recora/"}),(0,i.Y)("link",{rel:"alternate",hrefLang:"pt-BR",href:"https://uxcam.com/br/case-study/recora/"}),(0,i.Y)("link",{rel:"alternate",hrefLang:"x-default",href:"https://uxcam.com/case-study/recora/"}));var c=()=>(0,i.Y)(r.A,{data:o})}}]);